//! Toolkit-independent Timeline Sequencer working copy (ADR 0126).
//!
//! Persisted mutations are delegated to `TimelineAuthoringService`; this state owns only the
//! active document, clean-save baseline, selection, and transient Sequencer presentation state.

use engine::timeline::{TimelinePlaybackState, TimelineTick, TIMELINE_TICKS_PER_SECOND};
use engine_authoring::{
    validate_timeline, AssetId, TimelineAuthoringCommand, TimelineAuthoringError,
    TimelineAuthoringService, TimelineClip, TimelineClipId, TimelineDiagnostic, TimelineDocument,
    TimelineMarkerId, TimelineTrackId,
};
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum TimelineSelection {
    Track(TimelineTrackId),
    Clip(TimelineClipId),
    Marker(TimelineMarkerId),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub(crate) struct TimelineTrackViewState {
    pub(crate) muted: bool,
    pub(crate) solo: bool,
    pub(crate) locked: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum TimelineSnapMode {
    Frames,
    Seconds,
    Custom,
}

impl Default for TimelineSnapMode {
    fn default() -> Self {
        Self::Frames
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum TimelinePreviewMode {
    Stopped,
    Paused,
    Playing,
}

impl Default for TimelinePreviewMode {
    fn default() -> Self {
        Self::Stopped
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum TimelineClipGestureKind {
    Move,
    TrimStart,
    TrimEnd,
}

#[derive(Debug, Clone)]
pub(crate) struct TimelineClipGesture {
    pub(crate) clip: TimelineClipId,
    pub(crate) kind: TimelineClipGestureKind,
    pub(crate) original_start: TimelineTick,
    pub(crate) original_duration: TimelineTick,
    pub(crate) draft_start: TimelineTick,
    pub(crate) draft_duration: TimelineTick,
    pub(crate) snap_target: Option<TimelineTick>,
}

pub(crate) struct TimelineEditorState {
    relative_path: PathBuf,
    absolute_path: PathBuf,
    asset_id: Option<AssetId>,
    service: TimelineAuthoringService,
    clean_document: TimelineDocument,
    pub(crate) selection: Option<TimelineSelection>,
    pub(crate) selected_clips: BTreeSet<TimelineClipId>,
    pub(crate) track_view: BTreeMap<TimelineTrackId, TimelineTrackViewState>,
    pub(crate) zoom: f32,
    pub(crate) view_start: TimelineTick,
    pub(crate) playhead: TimelineTick,
    pub(crate) preview_mode: TimelinePreviewMode,
    pub(crate) preview_events: bool,
    pub(crate) playback_rate: f32,
    pub(crate) loop_enabled: bool,
    pub(crate) loop_start: TimelineTick,
    pub(crate) loop_end: TimelineTick,
    pub(crate) snap_enabled: bool,
    pub(crate) snap_mode: TimelineSnapMode,
    pub(crate) custom_snap_ticks: i64,
    pub(crate) add_track_search: String,
    pub(crate) clip_gesture: Option<TimelineClipGesture>,
    pub(crate) status: Option<String>,
}

impl TimelineEditorState {
    pub(crate) fn open(
        relative_path: PathBuf,
        absolute_path: PathBuf,
        asset_id: Option<AssetId>,
    ) -> Result<Self, String> {
        let json = fs::read_to_string(&absolute_path).map_err(|error| error.to_string())?;
        let document: TimelineDocument =
            serde_json::from_str(&json).map_err(|error| error.to_string())?;
        Self::from_document(relative_path, absolute_path, asset_id, document)
    }

    pub(crate) fn from_document(
        relative_path: PathBuf,
        absolute_path: PathBuf,
        asset_id: Option<AssetId>,
        document: TimelineDocument,
    ) -> Result<Self, String> {
        let service = TimelineAuthoringService::new(document.clone())
            .map_err(|diagnostics| format_timeline_diagnostics(&diagnostics))?;
        let duration = document.duration.max(TimelineTick::new(1));
        Ok(Self {
            relative_path,
            absolute_path,
            asset_id,
            service,
            clean_document: document,
            selection: None,
            selected_clips: BTreeSet::new(),
            track_view: BTreeMap::new(),
            zoom: 1.0,
            view_start: TimelineTick::ZERO,
            playhead: TimelineTick::ZERO,
            preview_mode: TimelinePreviewMode::Stopped,
            preview_events: false,
            playback_rate: 1.0,
            loop_enabled: false,
            loop_start: TimelineTick::ZERO,
            loop_end: duration,
            snap_enabled: true,
            snap_mode: TimelineSnapMode::Frames,
            custom_snap_ticks: TIMELINE_TICKS_PER_SECOND / 10,
            add_track_search: String::new(),
            clip_gesture: None,
            status: None,
        })
    }

    pub(crate) fn relative_path(&self) -> &Path {
        &self.relative_path
    }

    pub(crate) fn absolute_path(&self) -> &Path {
        &self.absolute_path
    }

    pub(crate) fn asset_id(&self) -> Option<&AssetId> {
        self.asset_id.as_ref()
    }

    pub(crate) fn set_asset_id(&mut self, asset_id: Option<AssetId>) {
        self.asset_id = asset_id;
    }

    pub(crate) fn document(&self) -> &TimelineDocument {
        self.service.document()
    }

    pub(crate) fn is_dirty(&self) -> bool {
        self.service.document() != &self.clean_document
    }

    pub(crate) fn can_undo(&self) -> bool {
        self.service.can_undo()
    }

    pub(crate) fn can_redo(&self) -> bool {
        self.service.can_redo()
    }

    pub(crate) fn undo(&mut self) -> bool {
        let changed = self.service.undo();
        if changed {
            self.clamp_transient_state();
        }
        changed
    }

    pub(crate) fn redo(&mut self) -> bool {
        let changed = self.service.redo();
        if changed {
            self.clamp_transient_state();
        }
        changed
    }

    pub(crate) fn apply(
        &mut self,
        commands: Vec<TimelineAuthoringCommand>,
    ) -> Result<(), TimelineAuthoringError> {
        if commands.is_empty() {
            return Ok(());
        }
        let revision = self.service.revision();
        self.service.apply_transaction(revision, commands)?;
        self.clamp_transient_state();
        Ok(())
    }

    pub(crate) fn save(&mut self) -> Result<(), TimelineAuthoringError> {
        self.service.save(&self.absolute_path)?;
        self.clean_document = self.service.document().clone();
        Ok(())
    }

    pub(crate) fn diagnostics(&self) -> Vec<TimelineDiagnostic> {
        validate_timeline(self.service.document())
    }

    pub(crate) fn preview_document(&self) -> TimelineDocument {
        let mut document = self.service.document().clone();
        let has_solo = document.tracks.iter().any(|track| {
            self.track_view
                .get(&track.id)
                .is_some_and(|state| state.solo)
        });
        for track in &mut document.tracks {
            let view = self.track_view.get(&track.id).copied().unwrap_or_default();
            if view.muted || (has_solo && !view.solo) {
                track.enabled = false;
            }
        }
        document
    }

    pub(crate) fn frame_ticks(&self) -> i64 {
        let rate = self.service.document().display_rate;
        if rate.numerator == 0 {
            return TIMELINE_TICKS_PER_SECOND;
        }
        let numerator = TIMELINE_TICKS_PER_SECOND.saturating_mul(i64::from(rate.denominator));
        (numerator / i64::from(rate.numerator)).max(1)
    }

    pub(crate) fn pixels_per_second(&self) -> f32 {
        96.0 * self.zoom.clamp(0.1, 16.0)
    }

    pub(crate) fn ticks_per_pixel(&self) -> f64 {
        TIMELINE_TICKS_PER_SECOND as f64 / self.pixels_per_second() as f64
    }

    pub(crate) fn snap_tick(&self, raw: TimelineTick, extra: &[TimelineTick]) -> (TimelineTick, Option<TimelineTick>) {
        let duration = self.service.document().duration.max(TimelineTick::ZERO);
        let raw = raw.clamp(TimelineTick::ZERO, duration);
        if !self.snap_enabled {
            return (raw, None);
        }
        let grid = match self.snap_mode {
            TimelineSnapMode::Frames => self.frame_ticks(),
            TimelineSnapMode::Seconds => TIMELINE_TICKS_PER_SECOND,
            TimelineSnapMode::Custom => self.custom_snap_ticks.max(1),
        };
        let grid_tick = TimelineTick::new(round_to_grid(raw.get(), grid)).clamp(TimelineTick::ZERO, duration);
        let threshold = (self.ticks_per_pixel() * 8.0).ceil().max(1.0) as i64;
        let mut candidates = Vec::with_capacity(extra.len() + self.service.document().markers.len() + 2);
        candidates.push(grid_tick);
        candidates.push(self.playhead);
        candidates.extend(self.service.document().markers.iter().map(|marker| marker.tick));
        candidates.extend(extra.iter().copied());
        let best = candidates
            .into_iter()
            .filter(|candidate| (candidate.get() - raw.get()).abs() <= threshold)
            .min_by_key(|candidate| (candidate.get() - raw.get()).abs());
        (best.unwrap_or(grid_tick), best)
    }

    pub(crate) fn clip(&self, id: &TimelineClipId) -> Option<(&TimelineTrackId, &TimelineClip)> {
        self.service.document().tracks.iter().find_map(|track| {
            track.clips.iter().find(|clip| &clip.id == id).map(|clip| (&track.id, clip))
        })
    }

    pub(crate) fn select_clip(&mut self, clip: TimelineClipId, additive: bool) {
        if !additive {
            self.selected_clips.clear();
        }
        if additive && self.selected_clips.contains(&clip) {
            self.selected_clips.remove(&clip);
        } else {
            self.selected_clips.insert(clip.clone());
        }
        self.selection = Some(TimelineSelection::Clip(clip));
    }

    pub(crate) fn selected_clip_ids(&self) -> Vec<TimelineClipId> {
        self.selected_clips.iter().cloned().collect()
    }

    pub(crate) fn duplicate_selected_clips(&mut self) -> Result<(), TimelineAuthoringError> {
        let offset = self.frame_ticks();
        let mut commands = Vec::new();
        let mut created = BTreeSet::new();
        for selected in self.selected_clip_ids() {
            let Some((track, clip)) = self.clip(&selected) else { continue };
            let mut duplicate = clip.clone();
            duplicate.id = TimelineClipId::generate();
            duplicate.name = format!("{} Copy", duplicate.name);
            duplicate.start = duplicate.start.saturating_add(offset);
            if duplicate.end() > self.service.document().duration {
                duplicate.start = self.service.document().duration.saturating_add(-duplicate.duration.get());
            }
            created.insert(duplicate.id.clone());
            commands.push(TimelineAuthoringCommand::AddClip {
                track: track.clone(),
                clip: duplicate,
            });
        }
        self.apply(commands)?;
        if !created.is_empty() {
            self.selected_clips = created;
            self.selection = self
                .selected_clips
                .iter()
                .next()
                .cloned()
                .map(TimelineSelection::Clip);
        }
        Ok(())
    }

    pub(crate) fn delete_selected_clips(&mut self) -> Result<(), TimelineAuthoringError> {
        let commands = self
            .selected_clip_ids()
            .into_iter()
            .map(TimelineAuthoringCommand::RemoveClip)
            .collect::<Vec<_>>();
        self.apply(commands)?;
        self.selected_clips.clear();
        self.selection = None;
        Ok(())
    }

    pub(crate) fn update_preview_tick(&mut self, tick: TimelineTick, state: TimelinePlaybackState) {
        self.playhead = tick.clamp(TimelineTick::ZERO, self.service.document().duration);
        self.preview_mode = match state {
            TimelinePlaybackState::Playing => TimelinePreviewMode::Playing,
            TimelinePlaybackState::Paused => TimelinePreviewMode::Paused,
            TimelinePlaybackState::Stopped => TimelinePreviewMode::Stopped,
        };
    }

    fn clamp_transient_state(&mut self) {
        let duration = self.service.document().duration.max(TimelineTick::ZERO);
        self.playhead = self.playhead.clamp(TimelineTick::ZERO, duration);
        self.view_start = self.view_start.clamp(TimelineTick::ZERO, duration);
        self.loop_start = self.loop_start.clamp(TimelineTick::ZERO, duration);
        self.loop_end = self.loop_end.clamp(TimelineTick::ZERO, duration);
        self.selected_clips
            .retain(|clip| self.service.document().tracks.iter().any(|track| track.clips.iter().any(|item| &item.id == clip)));
        self.track_view
            .retain(|track, _| self.service.document().tracks.iter().any(|item| &item.id == track));
    }
}

fn round_to_grid(value: i64, grid: i64) -> i64 {
    if grid <= 1 {
        return value;
    }
    let quotient = value.div_euclid(grid);
    let remainder = value.rem_euclid(grid);
    if remainder.saturating_mul(2) >= grid {
        quotient.saturating_add(1).saturating_mul(grid)
    } else {
        quotient.saturating_mul(grid)
    }
}

fn format_timeline_diagnostics(diagnostics: &[TimelineDiagnostic]) -> String {
    diagnostics
        .iter()
        .map(|diagnostic| format!("[{}] {}", diagnostic.code, diagnostic.message))
        .collect::<Vec<_>>()
        .join("; ")
}

#[cfg(test)]
mod tests {
    use super::*;
    use engine_authoring::{TimelineTrack, TimelineTrackKind};

    fn state() -> TimelineEditorState {
        TimelineEditorState::from_document(
            PathBuf::from("cinematic.timeline.json"),
            PathBuf::from("cinematic.timeline.json"),
            None,
            TimelineDocument::new("cinematic", TimelineTick::new(96_000)),
        )
        .unwrap()
    }

    #[test]
    fn edits_undo_and_dirty_state_share_authoring_service() {
        let mut state = state();
        let track = TimelineTrack {
            id: TimelineTrackId::generate(),
            name: "events".to_owned(),
            kind: TimelineTrackKind::Event,
            enabled: true,
            binding: None,
            clips: Vec::new(),
        };
        state
            .apply(vec![TimelineAuthoringCommand::AddTrack(track)])
            .unwrap();
        assert!(state.is_dirty());
        assert!(state.can_undo());
        assert!(state.undo());
        assert!(!state.is_dirty());
        assert!(state.redo());
        assert!(state.is_dirty());
    }

    #[test]
    fn frame_snapping_uses_document_display_rate() {
        let mut state = state();
        state.document();
        let (tick, _) = state.snap_tick(TimelineTick::new(810), &[]);
        assert_eq!(tick, TimelineTick::new(800));
    }
}
